@hdlmacro
def pmux_generator(ctx, sigarray, selectors, data):
	"Parallel multiplexer with selector signals"
	n = len(sigarray)
	_if = ctx.If
	for i in range(0, n):
		walk =	_if(selectors[i]).Then(
				data.set(sigarray[i])
			)
		_if = walk.Elif

	walk = walk.Else( data.set( work.DontCare(8, "-") ) )
	yield [ walk ]
	


